-- Idempotent shared-content seed: workflow_templates, workflow_steps,
-- checklist_templates (14yhc7kw7b2 Stage 1). Every template sourced from
-- Opeke where it exists there; 'Trustee Elections and Term Review' sourced
-- from Tineka (confirmed byte-identical to Terere's own copy) since Opeke
-- is the one missing it. checklist_templates sourced from Opeke, the only
-- project that has any. Scanned first for marae-specific words (Opeke,
-- Ōpōtiki, Waioweka, Tineka, Terere, Tūhoe, personal names) -- zero hits.
--
-- Never overwrites an existing row: every insert is a SELECT ... WHERE NOT
-- EXISTS against this project's own current rows, keyed by template name,
-- (template name, step_order), or checklist label -- not ON CONFLICT, since
-- none of these columns has a unique constraint to conflict on.

insert into workflow_templates (name, description, category, is_active)
select v.name, v.description, v.category, v.is_active
from (values
  ('AGM Preparation', 'Prepare and run the Annual General Meeting from planning through to filing with the Maori Land Court', 'governance', true),
  ('Annual Asset Inspection', 'Full annual inspection of all marae assets with condition ratings updated', 'maintenance', true),
  ('Building Maintenance and Repair', 'Manage a building repair or maintenance job from fault identification through to payment and asset update', 'maintenance', true),
  ('Charter Review and Update', 'Review and update the marae charter including beneficiary consultation and Maori Land Court filing', 'governance', true),
  ('Civil Defence Emergency Plan Review', 'Annual review and update of the marae civil defence and emergency management plan', 'compliance', true),
  ('Contractor Vetting and Approval', 'Vet and approve a new contractor before they work on the marae', 'operations', true),
  ('Drought / Water Shortage Response', 'Staged response to a developing water shortage -- monitor conditions, cut non-essential use early, protect your emergency reserve, and follow real restrictions as conditions worsen.', 'compliance', true),
  ('Evacuation Routes Review', 'Annual review and communication of marae evacuation routes, including accessibility routes.', 'compliance', true),
  ('Facility Hire Agreement', 'Process a facility hire request from enquiry through to post-event close', 'operations', true),
  ('Fire Safety Compliance Check', 'Annual fire safety review covering evacuation plans, equipment and training', 'compliance', true),
  ('Food Safety Compliance', 'Annual food safety review and registration renewal for the wharekai', 'compliance', true),
  ('Generator Test and Service', 'Monthly load test, fuel check, and service log for the marae backup generator.', 'compliance', true),
  ('Grant Application', 'Manage a grant application from opportunity identification through to reporting', 'funding', true),
  ('Health & Safety Incident Response', 'Manage a health and safety incident from report through to resolution and compliance update', 'compliance', true),
  ('Heat Pump Service', 'Full service process from contractor contact to asset record update', 'maintenance', true),
  ('Marae Emergency Readiness Starter Pack', 'Essential first steps to get your marae prepared for emergencies and civil defence events', 'compliance', true),
  ('Marae Insurance Renewal', 'Manage annual insurance renewal from review through to confirmed cover', 'compliance', true),
  ('Marae Structure Storm Readiness Check', 'Six-monthly visual inspection of the marae structure for storm readiness.', 'compliance', true),
  ('MaraeHub Onboarding', 'Set up your MaraeHub account step by step so your marae gets the most out of the platform from day one', 'operations', true),
  ('New Trustee Appointment', 'Onboard a newly elected trustee from election through to Maori Land Court notification and system access', 'governance', true),
  ('Quarterly Trustee Meeting', 'Prepare, run and follow up a quarterly trustee meeting', 'governance', true),
  ('Risk Remediation Plan', 'A structured response plan for a high-rated, physical risk -- inspect the real extent of the issue, get quotes, decide how to proceed, schedule the work, and record the outcome.', 'maintenance', true),
  ('Role Setup', 'Onboarding process for a trustee taking on a committee role: practical setup, learning the role, and establishing its recurring duties.', 'governance', true),
  ('Tangihanga Preparation', 'Coordinate marae facilities, logistics and support for a tangihanga', 'operations', true),
  ('Trustee Elections and Term Review', 'Election or term-renewal process for marae trustees, per charter requirements.', 'governance', true),
  ('Water Contamination Response', 'Incident response for a suspected or confirmed unsafe drinking water supply -- stop use, notify the right people, retest, and confirm safe before resuming.', 'compliance', true),
  ('Water Tank Inspection', 'Six-monthly inspection of the emergency water supply tank for leaks, contamination, and pump operation.', 'compliance', true)
) as v(name, description, category, is_active)
where not exists (select 1 from workflow_templates wt where wt.name = v.name);

