insert into checklist_templates (label, items, sort_order, active)
select v.label, v.items::jsonb, v.sort_order, v.active
from (values
  ('Lock all doors and windows', NULL, 0, true),
  ('Turn off all lights', NULL, 1, true),
  ('Check for left belongings', NULL, 2, true),
  ('Empty rubbish bins', NULL, 3, true),
  ('Report any damage to trustees', NULL, 4, true)
) as v(label, items, sort_order, active)
where not exists (select 1 from checklist_templates ct where ct.label = v.label);
